import {
    BooleanColumn,
    DecimalColumn,
    ReferenceColumn,
    StringColumn,
    TableNameColumn,
    TranslatedFieldColumn,
    ConditionsColumn,
    UserRolesColumn,
    Table,
    DomainIdColumn,
    DomainPathColumn,
    GenericColumn,
} from '../../db'

export const sys_app_module = Table({
    name: 'sys_app_module',
    schema: {
        active: BooleanColumn({ mandatory: false, label: 'Active', read_only: false, active: true, default: true }),
        application: ReferenceColumn({
            mandatory: false,
            label: 'Application menu',
            read_only: false,
            active: true,
            referenceTable: 'sys_app_application',
        }),
        assessment: ReferenceColumn({
            mandatory: false,
            label: 'Assessment',
            read_only: false,
            active: true,
            referenceTable: 'asmt_metric_type',
        }),
        device_type: StringColumn({
            mandatory: false,
            label: 'Device type',
            read_only: false,
            active: true,
            maxLength: 40,
            dropdown: 'dropdown_with_none',
            choices: {
                any: { label: 'Any', inactive: false, language: 'en' },
                browser: { label: 'Browser', inactive: false, language: 'en' },
                mobile: { label: 'Mobile', inactive: false, language: 'en' },
            },
        }),
        filter: ConditionsColumn({ mandatory: false, label: 'Filter', read_only: false, active: true }),
        hint: TranslatedFieldColumn({ mandatory: false, label: 'Hint', read_only: false, active: true }),
        homepage: ReferenceColumn({
            mandatory: false,
            label: 'Homepage',
            read_only: false,
            active: true,
            referenceTable: 'sys_portal_page',
        }),
        image: GenericColumn({
            mandatory: false,
            label: 'Image (UI11)',
            read_only: false,
            active: true,
            column_type: 'image',
        }),
        link_type: StringColumn({
            mandatory: false,
            label: 'Link type',
            read_only: false,
            active: true,
            default: 'LIST',
            maxLength: 40,
            dropdown: 'dropdown_with_none',
            choices: {
                LIST: { label: 'List of Records', inactive: false, language: 'en' },
                FILTER: { label: 'List Filter', inactive: false, language: 'en' },
                HTML: { label: 'HTML (from Arguments:)', inactive: false, language: 'en' },
                ASSESSMENT: { label: 'Assessment', inactive: false, language: 'en' },
                SEARCH: { label: 'Search Screen', inactive: false, language: 'en' },
                SURVEY: { label: 'Survey', inactive: false, language: 'en' },
                SCRIPT: { label: 'Script (from Arguments:)', inactive: false, language: 'en' },
                CONTENT_PAGE: { label: 'Content Page', inactive: false, language: 'en' },
                REPORT: { label: 'Run a Report', inactive: false, language: 'en' },
                DIRECT: { label: 'URL (from Arguments:)', inactive: false, language: 'en' },
                DOC_LINK: { label: 'Documentation Link', inactive: false, language: 'en' },
                NEW: { label: 'New Record', inactive: false, language: 'en' },
                MAP: { label: 'Map Page', inactive: false, language: 'en' },
                HOMEPAGE: { label: 'Homepage', inactive: true, language: 'en' },
                SEPARATOR: { label: 'Separator', inactive: false, language: 'en' },
                TIMELINE: { label: 'Timeline Page', inactive: false, language: 'en' },
                DETAIL: { label: 'Single Record', inactive: false, language: 'en' },
            },
        }),
        map_page: ReferenceColumn({
            mandatory: false,
            label: 'Map page',
            read_only: false,
            active: true,
            referenceTable: 'cmn_map_page',
        }),
        mobile_title: TranslatedFieldColumn({
            mandatory: false,
            label: 'Mobile title',
            read_only: false,
            active: true,
        }),
        mobile_view_name: StringColumn({
            mandatory: false,
            label: 'Mobile view name',
            read_only: false,
            active: true,
            default: 'Mobile',
            maxLength: 40,
            dropdown: 'none',
        }),
        name: TableNameColumn({ mandatory: false, label: 'Table', read_only: false, active: true }),
        order: DecimalColumn({ mandatory: false, label: 'Order', read_only: false, active: true }),
        override_menu_roles: BooleanColumn({
            mandatory: false,
            label: 'Override application menu roles',
            read_only: false,
            active: true,
            default: false,
        }),
        query: StringColumn({
            mandatory: false,
            label: 'Arguments',
            read_only: false,
            active: true,
            maxLength: 3500,
            dropdown: 'none',
        }),
        report: ReferenceColumn({
            mandatory: false,
            label: 'Report',
            read_only: false,
            active: true,
            referenceTable: 'sys_report',
        }),
        require_confirmation: BooleanColumn({
            mandatory: false,
            label: 'Require confirmation',
            read_only: false,
            active: true,
            default: true,
        }),
        roles: UserRolesColumn({ mandatory: false, label: 'Roles', read_only: false, active: true }),
        sys_domain: DomainIdColumn({
            mandatory: false,
            label: 'Domain',
            read_only: false,
            active: true,
            default: 'global',
        }),
        sys_domain_path: DomainPathColumn({
            mandatory: false,
            label: 'Domain Path',
            read_only: false,
            active: true,
            default: '/',
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
        sys_overrides: ReferenceColumn({
            mandatory: false,
            label: 'Overrides',
            read_only: false,
            active: true,
            referenceTable: 'sys_app_module',
        }),
        timeline_page: ReferenceColumn({
            mandatory: false,
            label: 'Timeline page',
            read_only: false,
            active: true,
            referenceTable: 'cmn_timeline_page',
        }),
        title: TranslatedFieldColumn({ mandatory: false, label: 'Title', read_only: false, active: true }),
        uncancelable: BooleanColumn({
            mandatory: false,
            label: 'Uncancelable by Other Modules',
            read_only: false,
            active: true,
            default: false,
        }),
        view_name: StringColumn({
            mandatory: false,
            label: 'View name',
            read_only: false,
            active: true,
            default:
                "javascript:var viewDefault='';if(current.device_type=='mobile') viewDefault='Mobile';else if(!current.application.nil() && current.application.device_type=='mobile' && current.device_type.nil()) viewDefault='Mobile';viewDefault",
            maxLength: 40,
        }),
        window_name: StringColumn({
            mandatory: false,
            label: 'Window name',
            read_only: false,
            active: true,
            maxLength: 40,
            dropdown: 'none',
        }),
    },
})
